"""Arrange complete3D authoring-guide views into sheets, never final anatomy."""
from pathlib import Path
import json
from PIL import Image,ImageDraw
P=Path(__file__).resolve().parent.parent
samples=json.loads((P/'authoring/atlas_pose_plan.json').read_text());tasks=[]
for kind,count,rows,cellsize in [('transition',8,2,(1024,1536)),('overhead',16,4,(768,768))]:
 selected=[s for s in samples if s['kind']==kind]
 for start in range(0,len(selected),count):
  group=selected[start:start+count];name=f'{kind}_{start//count:02d}';out=P/f'atlases/{name}_guide.png';sourcefiles=[P/f'authoring/atlas_pose_guides/{s["id"]}.png' for s in group]
  if any(not f.exists() for f in sourcefiles):continue
  if not out.exists():
   atlas=Image.new('RGBA',(4*cellsize[0],rows*cellsize[1]),'#4c525c');draw=ImageDraw.Draw(atlas)
   for n,(s,source) in enumerate(zip(group,sourcefiles)):
    im=Image.open(source).convert('RGBA')
    if kind=='overhead':im=im.crop((128,576,896,1344))
    x=n%4*cellsize[0];y=n//4*cellsize[1];atlas.alpha_composite(im,(x,y));draw.rectangle((x,y,x+cellsize[0]-1,y+cellsize[1]-1),outline='#ffdd88',width=3);draw.text((x+16,y+12),f'CELL {n}: '+(f'T{s["index"]:03d} / ' if kind=='transition' else '')+f'PHASE{s["phase"]:02d} / EL{s["elevation"]:.2f}',fill='white')
   for n in range(len(group),count):
    x=n%4*cellsize[0];y=n//4*cellsize[1];draw.text((x+40,y+80),'EMPTY CELL: no character',fill='white')
   atlas.save(out)
  phaseplan=', '.join(f'cell{n}='+('tick'+str(s['index'])+'/' if kind=='transition' else '')+f'phase{s["phase"]:02d}@{s["elevation"]:.2f}deg' for n,s in enumerate(group));angle=max(s['elevation'] for s in group);identity=P/('authoring/approved_face_identity_reference.png' if angle<55 else 'authoring/helmet_crown_identity_reference.png')
  interval=('These are8 successive CAMERA/TIME poses, two60Hz ticks apart. Every cell has its own exact elevated camera; do not replace them with a generic contact strip.' if kind=='transition' else 'These are16 CONSECUTIVE1/60second running phases from ONLY PART of the48posecycle, NOT16 evenly spaced poses of a fullcycle. Do not reinterpret them as fullcyclekeys.')
  if kind=='overhead':interval+=[' The interval starts RIGHT contact0 and ends in LEFT recovery15; LEFT contact24 is not in thissheet. RIGHT sword arm passes from rear0 toward neutral12 then forward.',' LEFT contact24 occurs inside this interval; RIGHT sword arm approaches forwardapex24 then returns. Follow the actual16 different guideposes.',' RIGHT leg recovers high36 then unfolds toward its NEXT contact0 after thissheet. RIGHT arm passes neutral36 toward rear48. Do not duplicate0 as47.'][start//16]
  pr=f'''Create ONE TRANSPARENT ATLAS in the EXACT{4}columns x{rows}rows grid of reference1. There are{len(group)} complete WHOLE-FIGURE drawings, one in each occupiedcell; anymarkedemptycellsstayempty. Reference1 consists of TRUE BLENDER3D camera/pose guides and OWNS each cell's exact anatomy, angle, phase, relative physicalscale and placement. Otherreferences are small approved face/helmet/navy/leather/kneeplate material identity crops ONLY, not anoldfullbodypose.\nExact row-major plan: {phaseplan}. {interval}\nIndividually redraw EVERY cell as one coherent naturallyproportioned painted allied Crown soldier, maintaining the guide's connected hip-knee-calf-ankle and shoulder-elbow-glove chains. Do not build a detached rig,interpolate,warp,crossfade or duplicate aheldpose. The nearANDfar limbs must progress as their own actualguide in eachcell, including support/compression/pushoff/flight/recovery and both opposing contacts. If a guideankle is folded BEHIND a forward knee, the painted boot stays back/up there; never turn it into a long frontal shin or an earlycontact. Exactlytwo anatomical legs/two feet andtwoarms, whethervisibleorcorrectlyoccluded; no extra3rdboot,hand or old fragments.\nThe runner travels toward imageBOTTOM. AnatomicalRIGHT/imageLEFT securely holds ONE sword in its LEATHER glove, blade world-DOWN/OUTSIDE with true-cameraforeshortening. LEFT/imageRIGHT forearm carries ONE plain upright boss shield; follow its real plane/thickness, becoming a thin edge/rim near overhead. Do not showa fullroundshieldface at82degrees. Natural right sword-arm pump and leftshieldcounterbalance, hands attached to real wrists.\nEvery cell is the exact current ordinary allied Crown model: youngman/brownhair/focusedface only whenphysicallyvisible,plain polished open steelhelmet,simple silver/steelplate onchest/shoulders/arms,smallarticulatedkneecaps/shortupper-shinlames onactualknees,charcoalquiltedtrousers,NAVYsplittabardwithtailsshortandbehind,brownleathergloves/boots. No red/goldroyalcommander,enemy purpleblack,newcape or modelchanges. Matchapproved detailed painted fantasy cinematic materials andthindarkouteroutline. Replace theguidesimple3Dvolumes withrealhumananatomy,notliteralcylinders.\nTruevolume/camera inEVERY cell: preservephysicalhelmet/rigidshoulder size, not occupiedfigureheight. Highcamera bodies genuinelyforeshorten; do NOTstretchtofillcell. Nearoverhead theheadleansFORWARD/downscreen ahead ofpelvis,withwaist/tailsbehind/up; no uprightfrontaltorso hangingbelow a topviewhelmet. Head/shoulders mayoccludewaist/legs. Atnear82degrees thehelmet/brimhidesfaceandeyes; no facepaintedthroughcrown. Keep eachcorrectlyfoldedbootbehinditsknee rather than extendinga genericlongleg.\nUse theexact guidegrid/aspect, equalcellboundaries and generouspercellmargins; no figurecrosses intoaneighbor. Keep helmet,swordtip,shieldandbothactualboots whollyinsideitscell. Preserve relative physicalwidth/density and the internalgroundroot fromeachguide; blankspaceisintentional. Wholecompletefiguresonly. TRUE CLEAN TRANSPARENT RGBA outsideeveryfigure, no grayfloor/shadow/haze/glow/backgroundrectangle,sheetlines,labels,cellnumbers,text,arrows orguidemarks. Remove all guidecaptionsandborders. Do notaddanythingtotheemptycells.\n'''
  pp=P/f'atlases/{name}_prompt.txt';pp.write_text(pr);t={'name':name,'kind':kind,'columns':4,'rows':rows,'reference_cell_size':list(cellsize),'reference_canvas':[4*cellsize[0],rows*cellsize[1]],'samples':group,'prompt_file':str(pp),'referenced_image_paths':[str(out),str(identity),str(P/'authoring/navy_cloth_identity_reference.png'),str(P/'authoring/leather_glove_identity_reference.png'),str(P/'authoring/knee_plate_only_material_reference.png')],'output':str(P/f'atlases/{name}.png')};tasks.append(t)
(P/'atlases/tasks.json').write_text(json.dumps(tasks,indent=2)+'\n');print('Readyatlases:',[t['name'] for t in tasks])
